(()=>{
'use strict';
const CD_KEYS=['dc1','dc2','dc3','cd13','cd123'];
const N=value=>{if(value==null)return 0;if(typeof value==='number')return Number.isFinite(value)?value:0;const number=Number(String(value).replace(/,/g,'').replace(/%/g,'').replace(/[()]/g,'').trim());return Number.isFinite(number)?number:0};
const norm=value=>String(value??'').replace(/\s+/g,' ').trim();
const compact=value=>norm(value).replace(/\s+/g,'').toUpperCase();
function isCd123Name(t){return t.includes('CD1+2+3')||t.includes('CD1+CD2+CD3')||/(^|[^0-9])CD123([^0-9]|$)/.test(t)}
function hasCdName(text,key){const value=compact(text);if(key==='cd123')return isCd123Name(value);if(key==='cd13')return value.includes('CD1+CD3');const number=key.replace('dc','');if(value.includes('CD1+CD3')||isCd123Name(value))return false;return new RegExp('(^|[^0-9])CD'+number+'([^0-9]|$)').test(value)||new RegExp('(^|[^0-9])DC'+number+'([^0-9]|$)').test(value)}
function findVal(object,key,kind){const keys=Object.keys(object||{});const thai=kind==='target'?'เป้าหมาย':kind==='actual'?'การกระจาย':'INDEX';const english=kind==='target'?'TARGET':kind==='actual'?'ACTUAL':'INDEX';for(const name of keys){const normalized=compact(name);if(!hasCdName(name,key))continue;if(normalized.includes(compact(thai))||normalized.includes(english))return N(object[name])}return 0}
function cdMetric(row,key){const direct=row?.[key]||{};let target=N(direct.target),actual=N(direct.actual),index=N(direct.index);const source=row?.sellerReport||row?.cd||{};if(!target)target=findVal(source,key,'target');if(!actual)actual=findVal(source,key,'actual');if(!index)index=findVal(source,key,'index');if(target&&actual)index=actual/target*100;else if(index&&index<=1.5)index*=100;return{target,actual,index}}
function moqVal(object,exact=[],contains=[]){const keys=Object.keys(object||{}),exactKeys=exact.map(compact),containsKeys=contains.map(compact);let key=keys.find(name=>exactKeys.includes(compact(name)));if(!key)key=keys.find(name=>containsKeys.some(part=>compact(name).includes(part)));return key?N(object[key]):0}
function moqMetric(row){const direct=row?.moq||{},source=row?.sellerReport||{},sellerTarget=moqVal(source,['เป้าหมายการกระจาย SBD'],['เป้าหมายการกระจายSBD']),sellerActual=moqVal(source,['การกระจาย SBD MOQ'],['SBD MOQ','การกระจายSBDMOQ']),sellerIndex=moqVal(source,['Index MOQ 75%'],['Index MOQ','MOQ 75']);let target=sellerTarget||N(direct.target),actual=sellerActual||N(direct.actual),index=sellerIndex||N(direct.index);if(target&&actual)index=actual/target*100;return{target,actual,index}}
function sumMoq(rows){let target=0,actual=0;(rows||[]).forEach(row=>{const metric=moqMetric(row);target+=N(metric.target);actual+=N(metric.actual)});return{target,actual,index:target?actual/target*100:0}}
function patchMoq(pack){if(!pack||!Array.isArray(pack.ps))return pack;pack.ps.forEach(row=>{row.moq=moqMetric(row)});const grouped=new Map();pack.ps.forEach(row=>{const id=row.ads||row.adsCode;if(!id)return;if(!grouped.has(id))grouped.set(id,[]);grouped.get(id).push(row)});(pack.ads||[]).forEach(row=>{const id=row.ads||row.adsCode||row.code,rows=grouped.get(id)||[];if(rows.length)row.moq=sumMoq(rows)});pack.ds=pack.ds||{};pack.ds.moq=sumMoq(pack.ps);return pack}
function addLabels(pack){const labels=pack.labels=pack.labels||{},first=(pack.ps||[]).find(row=>row?.sellerReport)||{},report=first.sellerReport||{};for(const key of CD_KEYS){const hit=Object.keys(report).find(name=>hasCdName(name,key)&&compact(name).includes('INDEX'));if(hit)labels[key]=key==='cd13'?'CD1+CD3':key==='cd123'?'CD1+2+3':norm(hit).replace(/^Index\s*/i,'')}}
function sum(rows,key){let target=0,actual=0,indexTotal=0,indexCount=0;(rows||[]).forEach(row=>{const metric=cdMetric(row,key);if(key==='cd123'&&N(metric.target)<=0)return;target+=N(metric.target);actual+=N(metric.actual);if(N(metric.index)>0){indexTotal+=N(metric.index);indexCount+=1}});return{target,actual,index:target?actual/target*100:(indexCount?indexTotal/indexCount:0)}}
function patchCdOnly(pack){if(!pack||!Array.isArray(pack.ps))return pack;addLabels(pack);pack.ps.forEach(row=>CD_KEYS.forEach(key=>{row[key]=cdMetric(row,key)}));const grouped=new Map();pack.ps.forEach(row=>{const id=row.ads||row.adsCode;if(!id)return;if(!grouped.has(id))grouped.set(id,[]);grouped.get(id).push(row)});(pack.ads||[]).forEach(row=>{const id=row.ads||row.adsCode||row.code,rows=grouped.get(id)||[];CD_KEYS.forEach(key=>{row[key]=sum(rows,key)})});pack.ds=pack.ds||{};CD_KEYS.forEach(key=>{pack.ds[key]=sum(pack.ps||[],key)});return pack}
function codeOf(row){return String(row?.ps||row?.psCode||row?.ads||row?.adsCode||row?.code||'').trim()}
function indexBy(rows){const map=new Map();(rows||[]).forEach(row=>{const code=codeOf(row);if(code)map.set(code,row)});return map}
function copyCd(dst,src){if(!dst||!src)return;CD_KEYS.forEach(key=>{if(src[key])dst[key]=src[key]})}
function copyMoq(dst,src){if(dst&&src?.moq)dst.moq=src.moq}
function mergeCd(base,full){if(!base||!full)return base;patchCdOnly(full);patchMoq(full);base.labels={...(base.labels||{}),...(full.labels||{})};const ps=indexBy(full.ps),ads=indexBy(full.ads);(base.ps||[]).forEach(row=>{const src=ps.get(codeOf(row));copyCd(row,src);copyMoq(row,src)});(base.ads||[]).forEach(row=>{const src=ads.get(codeOf(row));copyCd(row,src);copyMoq(row,src)});if(full.ds){base.ds=base.ds||{};copyCd(base.ds,full.ds);copyMoq(base.ds,full.ds)}base.__cdAdapter='performance-cd-adapter-v5-cd123';return base}
window.AYA_PERFORMANCE_LEGACY_ADAPTER=Object.freeze({CD_KEYS,isCd123Name,hasCdName,findVal,cdMetric,moqMetric,patchMoq,patchCdOnly,copyMoq,mergeCd});
})();
